import { useState, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Wifi, Download, Upload, Activity, MapPin, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';

function SpeedChecker() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  const API_BASE = process.env.REACT_APP_API_URL || window.location.origin;

  const runTest = useCallback(async () => {
    try {
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      // ================= PING =================
      const startPing = performance.now();
      await fetch(`${API_BASE}/api/ping`, { cache: 'no-store' });
      setPing(Math.round(performance.now() - startPing));

      // ================= DOWNLOAD =================
      const start = performance.now();
      let bytes = 0;

      for (let i = 0; i < 5; i++) {
        const res = await fetch(`${API_BASE}/api/download?size=5242880`, { cache: 'no-store' });

        const reader = res.body.getReader();

        while (true) {
          const { value, done } = await reader.read();
          if (done) break;

          bytes += value.byteLength;

          const mbps = (bytes * 8) / ((performance.now() - start) / 1000) / 1_000_000;

          setDownload(Math.round(mbps));
        }
      }

      // ================= UPLOAD (FIXED) =================
      const chunk = new Uint8Array(512 * 1024);
      let lastUpload = 0;

      for (let i = 0; i < 8; i++) {
        const res = await fetch(`${API_BASE}/api/upload`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/octet-stream',
          },
          body: chunk,
        });

        const data = await res.json();

        const speed = data.speed || 0;

        if (speed > 0) {
          lastUpload = speed;
          setUpload(Math.round(speed));
        }
      }

      setUpload(Math.round(lastUpload));
      setTesting(false);
    } catch (err) {
      console.error(err);
      setTesting(false);
      alert(err.message);
    }
  }, [API_BASE]);

  return (
    <div className="main-bg">
      <div className="container py-4">
        <div className="topbar">
          <h2 className="logo-text">Speed Checker</h2>

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'TESTING...' : 'RUN TEST'}
          </button>
        </div>

        {/* CARDS */}
        <div className="row g-4 mt-3">
          <MiniCard title="Download" value={`${download} Mbps`} icon={<Download />} />
          <MiniCard title="Upload" value={`${upload} Mbps`} icon={<Upload />} />
          <MiniCard title="Ping" value={`${ping} ms`} icon={<Activity />} />
          <MiniCard title="Status" value={testing ? 'Testing' : 'Ready'} icon={<Wifi />} />
        </div>

        {/* SPEED DISPLAY */}
        <div className="glass-panel mt-4">
          <motion.div key={download} animate={{ scale: 1 }}>
            <h1 className="speed-value">{download}</h1>
          </motion.div>
        </div>

        {/* FOOTER */}
        <footer className="footer-section">
          <Link to="/privacy-policy">Privacy</Link> |<Link to="/terms-of-service">Terms</Link> |
          <Link to="/about-us">About</Link>
        </footer>
      </div>
    </div>
  );
}

function MiniCard({ title, value, icon }) {
  return (
    <div className="mini-card">
      <div className="mini-icon">{icon}</div>
      <div className="mini-title">{title}</div>
      <div className="mini-value">{value}</div>
    </div>
  );
}

export default SpeedChecker;
